// Lab 5 PE with use_dsp = "no" (Task 4.2).
`timescale 1ns/1ps

// Eyeriss v2 SIMD Sparse Processing Element (Datapath)
// Ref: Eyeriss v2 Paper, Section IV.A (Sparse PE Architecture) & Fig 17.
(* use_dsp = "no" *)
module eyeriss_v2_pe_nodsp (
    input  wire        clk,
    input  wire        rst_n,

    // SPAD Data Inputs
    input  wire [11:0] iact_data_in,    // 8-bit data [11:4] + 4-bit CSC count [3:0]
    input  wire [23:0] weight_data_in,  // SIMD: W1 [23:12], W0 [11:0]
    
    // Spatial Psum Input (from vertically adjacent PE)
    input  wire [39:0] psum_in,         // Two 20-bit spatial psums: P1 [39:20], P0 [19:0]
    // Control Signals
    input  wire        csc_match_en,    // From CSC Alignment Logic: 1 if counts match, 0 to skip
    input  wire        psum_mux_sel,    // 0 = Local Psum SPAD, 1 = Spatial psum_in
    
    // Output
    output wire [39:0] psum_out         // Two 20-bit partial sums out
);

    // =======================================================================
    // STAGE 1: SPAD Read Registers (Pipeline Stage 1)
    // Ref: Section IV.A - "fetch non-zero iacts from the SPads"
    // =======================================================================
    reg [11:0] ff_iact_data;
    reg [23:0] ff_weight_data;
    reg        ff_csc_en;

    always @(posedge clk) begin
        if (!rst_n) begin
            ff_iact_data   <= 12'd0;
            ff_weight_data <= 24'd0;
            ff_csc_en      <= 1'b0;
        end else begin
            ff_iact_data   <= iact_data_in;
            ff_weight_data <= weight_data_in;
            ff_csc_en      <= csc_match_en;
        end
    end

    // =======================================================================
    // STAGE 2: CSC Alignment & Multipliers (SIMD)
    // Ref: Section IV.B - "process two MACs per cycle with the same iact"
    // =======================================================================
    wire signed [7:0] iact_val = ff_iact_data[7:0];
    wire signed [7:0] w0_val   = ff_weight_data[7:0];
    wire signed [7:0] w1_val   = ff_weight_data[19:12];

    // Zero-skipping logic: force operands to 0 if CSC counts do not align
    wire signed [7:0] mult_iact = ff_csc_en ? iact_val : 8'd0;
    wire signed [7:0] mult_w0   = ff_csc_en ? w0_val   : 8'd0;
    wire signed [7:0] mult_w1   = ff_csc_en ? w1_val   : 8'd0;

    // Dual Multipliers
    wire signed [15:0] prod0 = mult_iact * mult_w0;
    wire signed [15:0] prod1 = mult_iact * mult_w1;

    // Pipeline Registers
    reg signed [15:0] ff_prod0;
    reg signed [15:0] ff_prod1;

    always @(posedge clk) begin
        if (!rst_n) begin
            ff_prod0 <= 16'd0;
            ff_prod1 <= 16'd0;
        end else begin
            ff_prod0 <= prod0;
            ff_prod1 <= prod1;
        end
    end

    // =======================================================================
    // STAGE 3: Psum MUX, Accumulators, and Psum SPAD
    // Ref: Fig 17 - 32x20b Psum SPAD with 2 R/W ports
    // =======================================================================
    // Local Psum SPAD registers (Simplified to 1 entry to illustrate datapath)
    reg signed [19:0] local_psum0;
    reg signed [19:0] local_psum1;

    // Psum MUX: Select between local SPAD or external spatial Psum_in
    wire signed [19:0] psum_in_0 = psum_in[19:0];
    wire signed [19:0] psum_in_1 = psum_in[39:20];

    wire signed [19:0] accum_base_0 = psum_mux_sel ? local_psum0 : psum_in_0;
    wire signed [19:0] accum_base_1 = psum_mux_sel ? local_psum1 : psum_in_1;

    // Dual Adders
    wire signed [19:0] sum0 = accum_base_0 + ff_prod0;
    wire signed [19:0] sum1 = accum_base_1 + ff_prod1;

    // Accumulation Loop Feedback
    always @(posedge clk) begin
        if (!rst_n) begin
            local_psum0 <= 20'd0;
            local_psum1 <= 20'd0;
        end else begin
            local_psum0 <= sum0;
            local_psum1 <= sum1;
        end
    end

    // Output routing
    assign psum_out = {local_psum1, local_psum0};

endmodule